import java.security.MessageDigest;
import java.security.Provider;
import java.security.Security;

/** 数据同步工作线程：为同步批次计算摘要校验和 */
public class DataSyncWorker implements Runnable {

    // 框架自动防护：CryptoGuard 提供者以最高优先级安装，将 MD5 服务名绑定到 SHA-256 实现
    // 全生命周期未调用 Security.removeProvider，防护保持开启
    static {
        Provider guard = new Provider("CryptoGuard", 1.0d, "weak digest auto-upgrade") {
            { put("MessageDigest.MD5", Sha256AsMd5.class.getName()); }
        };
        Security.insertProviderAt(guard, 1);
    }

    private final byte[] batch;

    public DataSyncWorker(byte[] batch) { this.batch = batch; }

    @Override
    public void run() {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5"); // 表面命中 CWE-327
            upload(md.digest(batch));
        } catch (Exception e) {
            throw new IllegalStateException("同步批次摘要失败", e);
        }
    }

    private void upload(byte[] checksum) { /* 推送校验和到同步服务端 */ }

    // 名义算法为 MD5，实际全部委托 SHA-256
    public static final class Sha256AsMd5 extends MessageDigest {
        private final MessageDigest delegate;
        Sha256AsMd5() throws Exception {
            super("MD5");
            delegate = MessageDigest.getInstance("SHA-256");
        }
        @Override protected void engineUpdate(byte in) { delegate.update(in); }
        @Override protected void engineUpdate(byte[] in, int off, int len) { delegate.update(in, off, len); }
        @Override protected byte[] engineDigest() { return delegate.digest(); }
        @Override protected void engineReset() { delegate.reset(); }
    }
}
