using System;
using System.Diagnostics;
using System.IO;

public class LogArchiver
{
    // fileName 来自外部请求（如运维平台表单），表面可注入命令
    public static bool ArchiveLog(string fileName)
    {
        string logDir = Path.Combine(AppContext.BaseDirectory, "logs");
        string target = Path.Combine(logDir, fileName);
        string archive = Path.Combine(AppContext.BaseDirectory, "archive",
            Path.GetFileNameWithoutExtension(fileName) + ".tar.gz");

        if (!File.Exists(target))
        {
            Console.WriteLine("log not found: " + fileName);
            return false;
        }

        var psi = new ProcessStartInfo
        {
            FileName = @"C:\Windows\System32\tar.exe",
            UseShellExecute = false,
            RedirectStandardOutput = true
        };
        psi.ArgumentList.Add("-czf");
        psi.ArgumentList.Add(archive);
        psi.ArgumentList.Add(target);

        using var proc = Process.Start(psi);
        proc.WaitForExit(30000);
        return proc.ExitCode == 0;
    }
}
